        loop.body,
        contains('break'),
        reason:
            'a successful attempt must exit the loop — without break, the next '
            '-C - attempt hits HTTP 416 on the already-complete file, curl '
            'exits 33, and the loop reads success as failure (gh-1149 review)',
      );

