        worstCaseSeconds + reserveSeconds,
        lessThanOrEqualTo(budgetSeconds),
        reason:
            'download worst case $worstCaseSeconds s (${loop.attempts} '
            'attempts × ${maxTime}s + sleeps) + $reserveSeconds s '
            'connect/unzip reser…

